'use client';

import {
  TreeExpander,
  TreeIcon,
  TreeLabel,
  TreeNode,
  TreeNodeContent,
  TreeNodeTrigger,
  TreeProvider,
  TreeView,
} from '@/components/ui/tree';
import { type TreeNodeData, buildSimpleTree, getFileIcon } from '@/lib/tree-structure';
import { useState } from 'react';
import { ClientPreCode } from '../website/code-components/client-pre-code';

export function TreeCodeViewer({
  files,
}: {
  files: {
    id: string;
    fileName: string;
    virtualPath: string[];
    ext: string;
    raw: string;
    html: string;
  }[];
}) {
  const tree = buildSimpleTree(files);
  console.log('tree', tree);
  const [selectedId, setSelectedId] = useState(files[0]?.id);
  const fileMap = Object.fromEntries(files.map((f) => [f.id, f]));
  const selectedFile = selectedId ? fileMap[selectedId] : null;

  return (
    <div className='grid grid-cols-[250px_1fr] border bg-background overflow-hidden'>
      {/* LEFT */}
      <TreeProvider
        selectable
        multiSelect={false}
        defaultExpandedIds={[tree[0].name, 'ui', 'lib']}
        onSelectionChange={(ids) => {
          if (ids[0]) setSelectedId(ids[0]);
        }}
        className='border-r bg-card'
      >
        <TreeView>
          <RenderTree nodes={tree} />
        </TreeView>
      </TreeProvider>

      {/* RIGHT */}
      <div className='min-w-0 p-2'>
        {selectedFile ? (
          <ClientPreCode html={selectedFile.html} raw={selectedFile.raw} />
        ) : (
          <div className='p-6 text-sm text-muted-foreground'>Select a file</div>
        )}
      </div>
    </div>
  );
}

function RenderTree({ nodes, level = 0 }: { nodes: TreeNodeData[]; level?: number }) {
  return (
    <>
      {nodes.map((node, index) => {
        const isLast = index === nodes.length - 1;

        // 📁 FOLDER
        if (node.type === 'folder') {
          return (
            <TreeNode key={node.name} nodeId={node.name} level={level} isLast={isLast} isFolder>
              <TreeNodeTrigger>
                <TreeExpander hasChildren />
                <TreeIcon icon={getFileIcon('folder')} />
                <TreeLabel>{node.name}</TreeLabel>
              </TreeNodeTrigger>

              <TreeNodeContent hasChildren>
                <RenderTree nodes={node.children} level={level + 1} />
              </TreeNodeContent>
            </TreeNode>
          );
        }

        // 📄 FILE
        return (
          <TreeNode key={node.id} nodeId={node.id} level={level} isLast={isLast}>
            <TreeNodeTrigger>
              <TreeExpander />
              <TreeIcon icon={getFileIcon('file', node.ext, node.name)} />
              <TreeLabel>{node.name}</TreeLabel>
            </TreeNodeTrigger>
          </TreeNode>
        );
      })}
    </>
  );
}

'use client';

import { Tree, TreeItem, TreeItemLabel } from '@ui-sdk/react/tree';
import { cn } from '@/lib/utils';
import { ChevronRight, File, Folder, FolderOpen } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import {
  type ComponentProps,
  type HTMLAttributes,
  type ReactNode,
  createContext,
  useCallback,
  useContext,
  useId,
  useState,
} from 'react';

type TreeContextType = {
  expandedIds: Set<string>;
  selectedIds: string[];
  toggleExpanded: (nodeId: string) => void;
  handleSelection: (nodeId: string, ctrlKey: boolean) => void;
  showLines?: boolean;
  showIcons?: boolean;
  selectable?: boolean;
  multiSelect?: boolean;
  indent?: number;
  animateExpand?: boolean;
};

const TreeContext = createContext<TreeContextType | undefined>(undefined);

const useTree = () => {
  const context = useContext(TreeContext);
  if (!context) {
    throw new Error('Tree components must be used within a TreeProvider');
  }
  return context;
};

type TreeNodeContextType = {
  nodeId: string;
  level: number;
  isLast: boolean;
  isFolder?: boolean; // 👈 NEW
  parentPath: boolean[];
};

const TreeNodeContext = createContext<TreeNodeContextType | undefined>(undefined);

const useTreeNode = () => {
  const context = useContext(TreeNodeContext);
  if (!context) {
    throw new Error('TreeNode components must be used within a TreeNode');
  }
  return context;
};

export type TreeProviderProps = {
  children: ReactNode;
  defaultExpandedIds?: string[];
  showLines?: boolean;
  showIcons?: boolean;
  selectable?: boolean;
  multiSelect?: boolean;
  selectedIds?: string[];
  onSelectionChange?: (selectedIds: string[]) => void;
  indent?: number;
  animateExpand?: boolean;
  className?: string;
};

export const TreeProvider = ({
  children,
  defaultExpandedIds = [],
  showLines = true,
  showIcons = true,
  selectable = true,
  multiSelect = false,
  selectedIds,
  onSelectionChange,
  indent = 20,
  animateExpand = true,
  className,
}: TreeProviderProps) => {
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set(defaultExpandedIds));
  const [internalSelectedIds, setInternalSelectedIds] = useState<string[]>(selectedIds ?? []);

  const isControlled = selectedIds !== undefined && onSelectionChange !== undefined;
  const currentSelectedIds = isControlled ? selectedIds : internalSelectedIds;

  const toggleExpanded = useCallback((nodeId: string) => {
    setExpandedIds((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(nodeId)) {
        newSet.delete(nodeId);
      } else {
        newSet.add(nodeId);
      }
      return newSet;
    });
  }, []);

  const handleSelection = useCallback(
    (nodeId: string, ctrlKey = false) => {
      if (!selectable) {
        return;
      }

      let newSelection: string[];

      if (multiSelect && ctrlKey) {
        newSelection = currentSelectedIds.includes(nodeId)
          ? currentSelectedIds.filter((id) => id !== nodeId)
          : [...currentSelectedIds, nodeId];
      } else {
        newSelection = currentSelectedIds.includes(nodeId) ? [] : [nodeId];
      }

      if (!isControlled) {
        setInternalSelectedIds(newSelection);
      }

      // ALWAYS notify
      onSelectionChange?.(newSelection);
    },
    [selectable, multiSelect, currentSelectedIds, isControlled, onSelectionChange]
  );

  return (
    <TreeContext.Provider
      value={{
        expandedIds,
        selectedIds: currentSelectedIds,
        toggleExpanded,
        handleSelection,
        showLines,
        showIcons,
        selectable,
        multiSelect,
        indent,
        animateExpand,
      }}
    >
      <Tree
        mode={selectable ? (multiSelect ? 'multiple' : 'single') : 'none'}
        value={multiSelect ? currentSelectedIds : (currentSelectedIds[0] ?? null)}
        expanded={Array.from(expandedIds)}
        onExpandedChange={(next) => setExpandedIds(new Set(next))}
        onValueChange={(next) => {
          const selection = Array.isArray(next) ? next : next === null ? [] : [next];
          if (!isControlled) setInternalSelectedIds(selection);
          onSelectionChange?.(selection);
        }}
        aria-label='File tree'
        render={
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3, ease: 'easeOut' }}
          />
        }
        className={cn('w-full', className)}
      >
        {children}
      </Tree>
    </TreeContext.Provider>
  );
};

export type TreeViewProps = HTMLAttributes<HTMLDivElement>;

export const TreeView = ({ className, children, ...props }: TreeViewProps) => (
  <div className={cn('p-2', className)} {...props}>
    {children}
  </div>
);

export type TreeNodeProps = HTMLAttributes<HTMLDivElement> & {
  nodeId?: string;
  level?: number;
  isLast?: boolean;
  isFolder?: boolean; // 👈 NEW
  parentPath?: boolean[];
  children?: ReactNode;
};

export const TreeNode = ({
  nodeId: providedNodeId,
  level = 0,
  isLast = false,
  parentPath = [],
  isFolder = false, // ✅ DEFAULT = false
  children,
  className,
  onClick,
  ...props
}: TreeNodeProps) => {
  const generatedId = useId();
  const nodeId = providedNodeId ?? generatedId;

  // Build the parent path - mark positions where the parent was the last child
  const currentPath = level === 0 ? [] : [...parentPath];
  if (level > 0 && parentPath.length < level - 1) {
    // Fill in missing levels with false (not last)
    while (currentPath.length < level - 1) {
      currentPath.push(false);
    }
  }
  if (level > 0) {
    currentPath[level - 1] = isLast;
  }

  return (
    <TreeNodeContext.Provider
      value={{
        nodeId,
        level,
        isLast,
        parentPath: currentPath,
        isFolder,
      }}
    >
      <TreeItem
        value={nodeId}
        branch={isFolder || undefined}
        render={<div {...props} />}
        className={cn('select-none', className)}
      >
        {children}
      </TreeItem>
    </TreeNodeContext.Provider>
  );
};

export type TreeNodeTriggerProps = ComponentProps<typeof motion.div>;

export const TreeNodeTrigger = ({
  children,
  className,
  onClick,
  ...props
}: TreeNodeTriggerProps) => {
  const { selectedIds, toggleExpanded, handleSelection, indent } = useTree();
  const { nodeId, level } = useTreeNode();
  const isSelected = selectedIds.includes(nodeId);
  const { isFolder } = useTreeNode();
  return (
    <motion.div
      className={cn(
        'group relative mx-1 flex cursor-pointer items-center rounded-md px-3 py-2 transition-all duration-200',
        'hover:bg-muted',
        isSelected && 'bg-muted',
        className
      )}
      onClick={(e) => {
        e.stopPropagation();
        toggleExpanded(nodeId);

        // 🔥 Prevent folder from clearing file selection
        if (!isFolder) {
          handleSelection(nodeId, e.ctrlKey || e.metaKey);
        }

        onClick?.(e);
      }}
      style={{ paddingLeft: level * (indent ?? 0) + 8 }}
      whileTap={{ scale: 0.98, transition: { duration: 0.1 } }}
      {...props}
    >
      <TreeLines />
      {children as ReactNode}
    </motion.div>
  );
};

export const TreeLines = () => {
  const { showLines, indent } = useTree();
  const { level, isLast, parentPath } = useTreeNode();

  if (!showLines || level === 0) {
    return null;
  }

  return (
    <div className='pointer-events-none absolute top-0 bottom-0 left-0'>
      {/* Render vertical lines for all parent levels */}
      {Array.from({ length: level }, (_, index) => {
        const shouldHideLine = parentPath[index] === true;
        if (shouldHideLine && index === level - 1) {
          return null;
        }

        const lineLeft = index * (indent ?? 0) + 12;

        return (
          <div
            className='absolute top-0 bottom-0 border-l'
            key={lineLeft}
            style={{
              left: lineLeft,
              display: shouldHideLine ? 'none' : 'block',
            }}
          />
        );
      })}

      {/* Horizontal connector line */}
      <div
        className='absolute top-1/2 border-t'
        style={{
          left: (level - 1) * (indent ?? 0) + 12,
          width: (indent ?? 0) - 4,
          transform: 'translateY(-1px)',
        }}
      />

      {/* Vertical line to midpoint for last items */}
      {isLast && (
        <div
          className='absolute top-0 border-l'
          style={{
            left: (level - 1) * (indent ?? 0) + 12,
            height: '50%',
          }}
        />
      )}
    </div>
  );
};

export type TreeNodeContentProps = ComponentProps<typeof motion.div> & {
  hasChildren?: boolean;
};

export const TreeNodeContent = ({
  children,
  hasChildren = false,
  className,
  ...props
}: TreeNodeContentProps) => {
  const { animateExpand, expandedIds } = useTree();
  const { nodeId } = useTreeNode();
  const isExpanded = expandedIds.has(nodeId);

  return (
    <AnimatePresence>
      {hasChildren && isExpanded && (
        <motion.div
          animate={{ height: 'auto', opacity: 1 }}
          className='overflow-hidden'
          exit={{ height: 0, opacity: 0 }}
          initial={{ height: 0, opacity: 0 }}
          transition={{
            duration: animateExpand ? 0.3 : 0,
            ease: 'easeInOut',
          }}
        >
          <motion.div
            animate={{ y: 0 }}
            className={className}
            exit={{ y: -10 }}
            initial={{ y: -10 }}
            transition={{
              duration: animateExpand ? 0.2 : 0,
              delay: animateExpand ? 0.1 : 0,
            }}
            {...props}
          >
            {children}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

export type TreeExpanderProps = ComponentProps<typeof motion.div> & {
  hasChildren?: boolean;
};

export const TreeExpander = ({
  hasChildren = false,
  className,
  onClick,
  ...props
}: TreeExpanderProps) => {
  const { expandedIds, toggleExpanded } = useTree();
  const { nodeId } = useTreeNode();
  const isExpanded = expandedIds.has(nodeId);

  if (!hasChildren) {
    return <div className='mr-1 h-4 w-4' />;
  }

  return (
    <motion.div
      animate={{ rotate: isExpanded ? 90 : 0 }}
      className={cn('mr-1 flex h-4 w-4 cursor-pointer items-center justify-center', className)}
      onClick={(e) => {
        e.stopPropagation();
        toggleExpanded(nodeId);
        onClick?.(e);
      }}
      transition={{ duration: 0.2, ease: 'easeInOut' }}
      {...props}
    >
      <ChevronRight className='h-3 w-3 text-muted-foreground' />
    </motion.div>
  );
};

export type TreeIconProps = ComponentProps<typeof motion.div> & {
  icon?: ReactNode;
  hasChildren?: boolean;
};

export const TreeIcon = ({ icon, hasChildren = false, className, ...props }: TreeIconProps) => {
  const { showIcons, expandedIds } = useTree();
  const { nodeId } = useTreeNode();
  const isExpanded = expandedIds.has(nodeId);

  if (!showIcons) {
    return null;
  }

  const getDefaultIcon = () =>
    hasChildren ? (
      isExpanded ? (
        <FolderOpen className='h-4 w-4' />
      ) : (
        <Folder className='h-4 w-4' />
      )
    ) : (
      <File className='h-4 w-4' />
    );

  return (
    <motion.div
      className={cn(
        'mr-2 flex h-4 w-4 items-center justify-center text-muted-foreground',
        className
      )}
      transition={{ duration: 0.15 }}
      whileHover={{ scale: 1.1 }}
      {...props}
    >
      {icon || getDefaultIcon()}
    </motion.div>
  );
};

export type TreeLabelProps = HTMLAttributes<HTMLSpanElement>;

export const TreeLabel = ({ className, ...props }: TreeLabelProps) => (
  <TreeItemLabel
    render={<span {...props} />}
    className={cn('font flex-1 truncate text-sm text-primary/70', className)}
  />
);

import { Braces, FileJson, FileText, Folder } from 'lucide-react';

export type TreeNodeData =
  | {
      type: 'folder';
      name: string;
      children: TreeNodeData[];
    }
  | {
      type: 'file';
      id: string;
      name: string;
      ext: string;
    };

export function buildSimpleTree(files: any[]): TreeNodeData[] {
  const root: Record<string, any> = {};

  for (const file of files) {
    let current = root;

    for (const folder of file.virtualPath) {
      current[folder] ??= { __children: {} };
      current = current[folder].__children;
    }

    current[file.fileName] = file;
  }

  const toTree = (obj: any): TreeNodeData[] =>
    Object.entries(obj).map(([key, value]: any) => {
      if (value.__children) {
        return {
          type: 'folder',
          name: key,
          children: toTree(value.__children),
        };
      }

      return {
        type: 'file',
        id: value.id,
        name: value.fileName,
        ext: value.ext,
      };
    });

  return toTree(root);
}
