      strokeWidth='2'
      strokeLinecap='round'
      strokeLinejoin='round'
    ></path>
  </svg>
);

export function getFileIcon(type: 'folder' | 'file', ext?: string, name?: string) {
  if (type === 'folder') {
    return <Folder className='h-4 w-4 text-blue-500' />;
  }

  if (name === 'package.json') {
    return <FileJson className='h-4 w-4 text-green-500' />;
  }

  switch (ext) {
    case 'ts':
    case 'tsx':
      return <TypescriptIcon className='h-4 w-4 text-blue-600' />;
    case 'json':
      return <FileJson className='h-4 w-4 text-orange-500' />;
    default:
      return <FileText className='h-4 w-4 text-muted-foreground' />;
  }
}

